// Biomolecules - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'
// Note: this chapter has an increased share of assertion-reason, statement-based and count-type questions, per request.

export const BIOMOLECULES = [

  // ============ ANALYSIS OF CHEMICAL COMPOSITION ============
  { id: 'bmol-1', type: 'mcq', question: 'When living tissue is ground in trichloroacetic acid (TCA), the resulting acid-soluble pool typically contains:', options: ['Only macromolecules like proteins and nucleic acids', 'Small molecular weight organic compounds such as amino acids, sugars and nucleotides', 'Only inorganic salts', 'Only lipids'], correctIndex: 1, explanation: 'On grinding a tissue in TCA, the thick slurry separates into an acid-soluble pool (small molecules like amino acids, sugars, nucleotides) and an acid-insoluble fraction (macromolecules).', difficulty: 'medium' },
  { id: 'bmol-2', type: 'mcq', question: 'On analysing living tissue, the acid-insoluble fraction is mainly composed of:', options: ['Amino acids and simple sugars', 'Macromolecules such as proteins, nucleic acids, polysaccharides and lipids', 'Only inorganic ions', 'Only water'], correctIndex: 1, explanation: 'The acid-insoluble fraction obtained after TCA treatment mainly contains macromolecules like proteins, nucleic acids, polysaccharides and some lipids.', difficulty: 'medium' },
  { id: 'bmol-3', type: 'mcq', question: 'Elemental analysis shows that in living tissues, the most abundant element by weight is usually:', options: ['Carbon', 'Oxygen', 'Hydrogen', 'Nitrogen'], correctIndex: 1, explanation: 'When elemental analysis of a living tissue is performed, oxygen is found to be the most abundant element by weight, mainly because of the high water content.', difficulty: 'medium' },
  { id: 'bmol-4', type: 'assertion', question: 'Assertion (A): The elemental composition of a living tissue closely resembles that of non-living matter such as the earth\'s crust.\nReason (R): Both living and non-living matter are made of the same chemical elements available in nature, with no unique elements exclusive to living systems.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Elemental analysis of any living tissue does not show any elements unique to living matter — the same elements found in non-living matter (earth\'s crust) are present, confirming both statements.', difficulty: 'medium' },
  { id: 'bmol-5', type: 'count', question: 'Consider the following statements about elemental analysis of living tissue:\n1. Living tissue shows unique elements not found in non-living matter.\n2. Carbon, hydrogen, oxygen and nitrogen together constitute the bulk of living matter.\n3. The acid-soluble pool represents the biomacromolecular fraction.\n4. TCA treatment is used to separate small molecules from macromolecules.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 2 and 4 are correct. Statement 1 is wrong (no unique elements exist in living matter), and statement 3 is wrong (the acid-soluble pool contains small molecules, not macromolecules).', difficulty: 'hard' },

  // ============ BIOMOLECULES: OVERVIEW, MONOMERS, MACROMOLECULES ============
  { id: 'bmol-6', type: 'mcq', question: 'All the carbon compounds found in living organisms, obtained through chemical analysis, are collectively referred to as:', options: ['Micromolecules', 'Biomolecules', 'Metabolites', 'Cofactors'], correctIndex: 1, explanation: 'The organic compounds of living tissues, made up of carbon combined with hydrogen, oxygen, nitrogen etc., are collectively called biomolecules.', difficulty: 'easy' },
  { id: 'bmol-7', type: 'mcq', question: 'Amino acids, monosaccharides and nucleotides represent examples of:', options: ['Micromolecules (biomolecules of low molecular weight)', 'Macromolecules', 'Inorganic salts', 'Trace elements'], correctIndex: 0, explanation: 'Amino acids, sugars, nucleotides and similar compounds are relatively small in molecular weight and are called micromolecules.', difficulty: 'easy' },
  { id: 'bmol-8', type: 'mcq', question: 'Proteins, nucleic acids and polysaccharides are examples of:', options: ['Micromolecules', 'Macromolecules', 'Simple sugars', 'Amino acids'], correctIndex: 1, explanation: 'Proteins, nucleic acids and polysaccharides are macromolecules — the acid-insoluble fraction that is largely made of these polymers.', difficulty: 'easy' },
  { id: 'bmol-9', type: 'assertion', question: 'Assertion (A): Lipids, though part of the acid-insoluble fraction, are usually not classified as true macromolecules.\nReason (R): Lipids have a relatively low molecular weight compared to proteins, polysaccharides and nucleic acids.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Although lipids appear in the acid-insoluble fraction, their molecular weights are relatively low compared to true macromolecules, correctly explaining the assertion.', difficulty: 'hard' },
  { id: 'bmol-10', type: 'count', question: 'Consider the following biomolecules:\n1. Glucose\n2. Amino acid\n3. Cellulose\n4. Nucleotide\n5. Protein\nHow many of the above are classified as micromolecules?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 1, explanation: 'Glucose, amino acid and nucleotide are micromolecules; cellulose and protein are macromolecules (polymers). So three of the five are micromolecules.', difficulty: 'medium' },

  // ============ CARBOHYDRATES / POLYSACCHARIDES ============
  { id: 'bmol-11', type: 'mcq', question: 'Monosaccharides such as glucose, ribose and fructose are characterised by:', options: ['A free aldehyde or ketone group and two or more hydroxyl groups', 'The presence of only phosphate groups', 'Being polymers of amino acids', 'Being made up of nitrogenous bases'], correctIndex: 0, explanation: 'Monosaccharides are simple sugars possessing a free aldehyde or ketone group along with several hydroxyl groups.', difficulty: 'easy' },
  { id: 'bmol-12', type: 'mcq', question: 'When two monosaccharides are joined together by a glycosidic bond with the loss of a water molecule, the resulting sugar is called a:', options: ['Polysaccharide', 'Oligosaccharide (specifically a disaccharide)', 'Trisaccharide only', 'Monosaccharide derivative'], correctIndex: 1, explanation: 'Two monosaccharides joined by a glycosidic bond, with loss of a water molecule, form a disaccharide (a type of oligosaccharide), e.g., sucrose from glucose and fructose.', difficulty: 'medium' },
  { id: 'bmol-13', type: 'mcq', question: 'Long chains of sugars, running into hundreds of monosaccharide units, are called:', options: ['Monosaccharides', 'Disaccharides', 'Polysaccharides', 'Oligosaccharides'], correctIndex: 2, explanation: 'Polysaccharides are polymers made of long chains of monosaccharide units, e.g., cellulose, starch and glycogen.', difficulty: 'easy' },
  { id: 'bmol-14', type: 'mcq', question: 'Cellulose, a major structural polysaccharide of plant cell walls, is a polymer made up entirely of:', options: ['Fructose units', 'Glucose units', 'Amino sugar units', 'Ribose units'], correctIndex: 1, explanation: 'Cellulose is a homopolymer built exclusively of glucose units, forming a major component of plant cell walls.', difficulty: 'medium' },
  { id: 'bmol-15', type: 'mcq', question: 'Starch, the storage polysaccharide of plants, forms helical secondary structures and gives a characteristic colour reaction with iodine, producing:', options: ['A red colour', 'A blue-black colour', 'A green colour', 'No colour change'], correctIndex: 1, explanation: 'Starch is a homopolymer of glucose that forms helices as secondary structure and gives a characteristic blue-black colour with iodine.', difficulty: 'medium' },
  { id: 'bmol-16', type: 'mcq', question: 'Glycogen is the principal storage polysaccharide found in:', options: ['Plants', 'Animals and fungi', 'Bacteria only', 'Viruses'], correctIndex: 1, explanation: 'Glycogen is the storage polysaccharide of animals and fungi, analogous to starch in plants, and is a branched polymer of glucose.', difficulty: 'easy' },
  { id: 'bmol-17', type: 'mcq', question: 'Chitin, a polysaccharide found in the exoskeletons of arthropods and cell walls of fungi, is composed of repeating units of:', options: ['Glucose', 'N-acetylglucosamine', 'Galactose', 'Ribose'], correctIndex: 1, explanation: 'Chitin is a homopolymer built of N-acetylglucosamine units, providing structural support in arthropod exoskeletons and fungal cell walls.', difficulty: 'medium' },
  { id: 'bmol-18', type: 'mcq', question: 'In a polysaccharide molecule, individual monosaccharide units are linked together by which type of bond?', options: ['Peptide bond', 'Glycosidic bond', 'Phosphodiester bond', 'Hydrogen bond'], correctIndex: 1, explanation: 'Monosaccharides in a polysaccharide are joined through glycosidic bonds, formed with the loss of water molecules.', difficulty: 'easy' },
  { id: 'bmol-19', type: 'assertion', question: 'Assertion (A): Cellulose and starch, though both homopolymers of glucose, differ significantly in their properties and function.\nReason (R): The type of glycosidic linkage between glucose units (beta linkages in cellulose versus alpha linkages in starch) leads to different structural arrangements and biological roles.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Differences in glycosidic linkage type between glucose units explain why cellulose forms rigid structural fibres while starch acts as a coiled storage form, correctly explaining the assertion.', difficulty: 'hard' },
  { id: 'bmol-20', type: 'count', question: 'Consider the following statements about polysaccharides:\n1. Cellulose is found in plant cell walls.\n2. Glycogen is the storage polysaccharide of plants.\n3. Starch gives a blue-black colour with iodine.\n4. Chitin is composed of repeating units of N-acetylglucosamine.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — glycogen is the storage polysaccharide of animals and fungi, not plants (starch is the plant storage form).', difficulty: 'medium' },
  { id: 'bmol-21', type: 'statement', question: 'Statement I: All polysaccharides are homopolymers built of a single type of monosaccharide.\nStatement II: Peptidoglycan (murein) of bacterial cell walls is an example of a heteropolysaccharide.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect since some polysaccharides are heteropolymers (containing more than one type of monomer, e.g., peptidoglycan, which includes amino sugars). Statement II is correct.', difficulty: 'hard' },

  // ============ PROTEINS: AMINO ACIDS ============
  { id: 'bmol-22', type: 'mcq', question: 'Amino acids, the building blocks (monomers) of proteins, are organic compounds containing:', options: ['An amino group and a carboxyl group attached to the same carbon atom', 'Only a phosphate group', 'A nitrogenous base and a sugar', 'Two carboxyl groups and no amino group'], correctIndex: 0, explanation: 'An amino acid has both an amino group (–NH2) and an acidic group (–COOH) attached to the same central carbon atom.', difficulty: 'easy' },
  { id: 'bmol-23', type: 'mcq', question: 'Based on the nature of the R group (side chain), amino acids are classified as acidic, basic and neutral. This classification depends on the relative number of:', options: ['Sulphur atoms present', 'Amino and carboxyl groups in the side chain', 'Carbon atoms in the backbone', 'Hydrogen bonds formed'], correctIndex: 1, explanation: 'Amino acids are classified as acidic, basic or neutral depending on the relative number of amino and carboxyl groups present in the side chain (R group).', difficulty: 'medium' },
  { id: 'bmol-24', type: 'mcq', question: 'The total number of standard amino acids commonly found in proteins is:', options: ['10', '20', '25', '30'], correctIndex: 1, explanation: 'There are 20 types of standard amino acids commonly found in proteins, differing in their R group.', difficulty: 'easy' },
  { id: 'bmol-25', type: 'mcq', question: 'The bond formed between the carboxyl group of one amino acid and the amino group of another, with the loss of a water molecule, is called a:', options: ['Glycosidic bond', 'Peptide bond', 'Phosphodiester bond', 'Hydrogen bond'], correctIndex: 1, explanation: 'A peptide bond is formed between the –COOH group of one amino acid and the –NH2 group of the next, with elimination of water.', difficulty: 'easy' },
  { id: 'bmol-26', type: 'mcq', question: 'A chain of amino acids joined by peptide bonds, without regard to length, is generally called a:', options: ['Polynucleotide', 'Polypeptide', 'Polysaccharide', 'Glycoprotein'], correctIndex: 1, explanation: 'When amino acids are linked by peptide bonds in a chain, the resulting molecule is called a polypeptide; proteins are one or more polypeptides.', difficulty: 'easy' },
  { id: 'bmol-27', type: 'assertion', question: 'Assertion (A): Amino acids can act as both acids and bases.\nReason (R): An amino acid molecule possesses a free carboxyl group (which can donate H+) and a free amino group (which can accept H+), giving it amphoteric character.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The simultaneous presence of an acidic (–COOH) and a basic (–NH2) group makes amino acids amphoteric, exactly as explained in R.', difficulty: 'medium' },
  { id: 'bmol-28', type: 'count', question: 'Consider the following statements about amino acids:\n1. There are 20 standard amino acids found in proteins.\n2. Every amino acid has an amino group and a carboxyl group attached to the same carbon.\n3. Amino acids are linked by glycosidic bonds to form proteins.\n4. Amino acids can be classified as acidic, basic or neutral based on their R group.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — amino acids are linked by peptide bonds, not glycosidic bonds.', difficulty: 'medium' },

  // ============ PROTEIN STRUCTURE ============
  { id: 'bmol-29', type: 'mcq', question: 'The linear sequence of amino acids in a polypeptide chain, held together by peptide bonds, describes the:', options: ['Primary structure of a protein', 'Secondary structure of a protein', 'Tertiary structure of a protein', 'Quaternary structure of a protein'], correctIndex: 0, explanation: 'The primary structure of a protein refers to the linear sequence of amino acids as they occur in the polypeptide chain.', difficulty: 'easy' },
  { id: 'bmol-30', type: 'mcq', question: 'Coiled or folded patterns like alpha helices and beta pleated sheets, formed due to hydrogen bonding within a polypeptide, describe the:', options: ['Primary structure', 'Secondary structure', 'Tertiary structure', 'Quaternary structure'], correctIndex: 1, explanation: 'Secondary structure refers to regular, repeated folding patterns such as alpha helix and beta pleated sheets, stabilised by hydrogen bonds.', difficulty: 'medium' },
  { id: 'bmol-31', type: 'mcq', question: 'The overall three-dimensional folded shape of a single polypeptide chain, giving proteins their biologically active form, describes the:', options: ['Primary structure', 'Secondary structure', 'Tertiary structure', 'Quaternary structure'], correctIndex: 2, explanation: 'Tertiary structure represents the overall 3-D folding of a polypeptide into a compact, functionally active shape.', difficulty: 'medium' },
  { id: 'bmol-32', type: 'mcq', question: 'When two or more polypeptide subunits associate to form a functional protein, the arrangement of these subunits with respect to each other is called the:', options: ['Primary structure', 'Secondary structure', 'Tertiary structure', 'Quaternary structure'], correctIndex: 3, explanation: 'Quaternary structure describes how multiple polypeptide subunits (protomers) are spatially arranged with respect to each other, e.g., haemoglobin has four subunits.', difficulty: 'medium' },
  { id: 'bmol-33', type: 'mcq', question: 'Haemoglobin, made up of four polypeptide chains, is a classic example illustrating:', options: ['Primary structure only', 'Secondary structure only', 'Tertiary structure only', 'Quaternary structure'], correctIndex: 3, explanation: 'Haemoglobin consists of four subunits (two alpha and two beta chains), representing quaternary structure.', difficulty: 'easy' },
  { id: 'bmol-34', type: 'assertion', question: 'Assertion (A): The primary structure of a protein ultimately determines its higher-order structures (secondary, tertiary and quaternary).\nReason (R): The specific sequence of amino acids dictates the folding pattern and the types of bonds/interactions that stabilise the final three-dimensional shape of the protein.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since the amino acid sequence governs subsequent folding and interactions, R correctly explains why the primary structure determines higher-order protein structures.', difficulty: 'hard' },
  { id: 'bmol-35', type: 'matching', question: 'Match Column I (level of protein structure) with Column II (description):\nColumn I: A. Primary  B. Secondary  C. Tertiary  D. Quaternary\nColumn II: i. 3-D folding of a single chain  ii. Linear amino acid sequence  iii. Arrangement of multiple subunits  iv. Alpha helix/beta sheet folding', options: ['A-ii, B-iv, C-i, D-iii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-i, C-ii, D-iii', 'A-ii, B-iii, C-iv, D-i'], correctIndex: 0, explanation: 'Primary — linear sequence; Secondary — alpha helix/beta sheet; Tertiary — 3-D folding of one chain; Quaternary — arrangement of multiple subunits.', difficulty: 'medium' },
  { id: 'bmol-36', type: 'count', question: 'Consider the following statements about protein structure:\n1. Primary structure refers to the sequence of amino acids.\n2. Secondary structure involves regular folding patterns like alpha helices.\n3. Every protein necessarily has a quaternary structure.\n4. Tertiary structure describes the 3-D shape of a single polypeptide.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — quaternary structure exists only in proteins with more than one polypeptide subunit; single-chain proteins lack it.', difficulty: 'hard' },
  { id: 'bmol-37', type: 'statement', question: 'Statement I: All proteins, regardless of their function, are composed exclusively of the same 20 standard amino acids joined by peptide bonds.\nStatement II: The specific three-dimensional structure of a protein is essential for its correct biological function.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements are correct: proteins are built from the same 20 standard amino acids linked by peptide bonds, and their precise 3-D shape is essential for proper function.', difficulty: 'medium' },

  // ============ LIPIDS ============
  { id: 'bmol-38', type: 'mcq', question: 'Simple lipids such as fats and oils are generally esters of:', options: ['Glycerol and fatty acids', 'Sugars and phosphate groups', 'Amino acids and glycerol', 'Nitrogenous bases and sugars'], correctIndex: 0, explanation: 'Fats and oils are esters formed between glycerol (an alcohol) and fatty acids.', difficulty: 'easy' },
  { id: 'bmol-39', type: 'mcq', question: 'Fats that remain liquid at room temperature, typically due to a higher proportion of unsaturated fatty acids, are commonly called:', options: ['Waxes', 'Oils', 'Phospholipids', 'Glycolipids'], correctIndex: 1, explanation: 'Oils are fats containing more unsaturated fatty acids (with double bonds), which lowers their melting point, keeping them liquid at room temperature.', difficulty: 'medium' },
  { id: 'bmol-40', type: 'mcq', question: 'Fatty acids that contain one or more carbon-carbon double bonds in their hydrocarbon chain are called:', options: ['Saturated fatty acids', 'Unsaturated fatty acids', 'Amino fatty acids', 'Nucleotide fatty acids'], correctIndex: 1, explanation: 'Unsaturated fatty acids contain one or more double bonds in their hydrocarbon chain, in contrast to saturated fatty acids which contain none.', difficulty: 'easy' },
  { id: 'bmol-41', type: 'mcq', question: 'Lipids that contain a phosphorus-containing group in addition to fatty acids and glycerol, and are important components of cell membranes, are called:', options: ['Waxes', 'Phospholipids', 'Simple fats', 'Glycogen'], correctIndex: 1, explanation: 'Phospholipids contain a phosphate group along with two fatty acids esterified to glycerol; they are the principal component of cell membranes.', difficulty: 'medium' },
  { id: 'bmol-42', type: 'assertion', question: 'Assertion (A): Lipids are generally insoluble in water but soluble in organic solvents.\nReason (R): Lipids are largely hydrophobic molecules consisting predominantly of long hydrocarbon chains.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The hydrophobic hydrocarbon nature of lipids explains their insolubility in water and solubility in organic solvents, correctly explaining the assertion.', difficulty: 'medium' },

  // ============ NUCLEIC ACIDS ============
  { id: 'bmol-43', type: 'mcq', question: 'A nucleotide is composed of three components joined together, namely:', options: ['A nitrogenous base, a pentose sugar, and a phosphate group', 'An amino acid, a sugar and a fatty acid', 'A fatty acid, glycerol and phosphate', 'Two amino acids and a sugar'], correctIndex: 0, explanation: 'A nucleotide consists of a nitrogenous base, a pentose sugar (ribose or deoxyribose), and a phosphate group.', difficulty: 'easy' },
  { id: 'bmol-44', type: 'mcq', question: 'A nucleoside is different from a nucleotide in that a nucleoside lacks the:', options: ['Nitrogenous base', 'Pentose sugar', 'Phosphate group', 'Hydrogen bonds'], correctIndex: 2, explanation: 'A nucleoside consists only of a nitrogenous base linked to a sugar; when a phosphate group is added, it becomes a nucleotide.', difficulty: 'medium' },
  { id: 'bmol-45', type: 'mcq', question: 'The purine nitrogenous bases found in nucleic acids are:', options: ['Cytosine and thymine', 'Adenine and guanine', 'Uracil and thymine', 'Cytosine and uracil'], correctIndex: 1, explanation: 'Adenine and guanine are purines (double-ring structures), while cytosine, thymine and uracil are pyrimidines (single-ring structures).', difficulty: 'easy' },
  { id: 'bmol-46', type: 'mcq', question: 'Which nitrogenous base is found in RNA but not in DNA?', options: ['Adenine', 'Guanine', 'Uracil', 'Cytosine'], correctIndex: 2, explanation: 'Uracil is found in RNA, replacing thymine, which is characteristic of DNA.', difficulty: 'easy' },
  { id: 'bmol-47', type: 'mcq', question: 'Adjacent nucleotides in a polynucleotide chain (as in DNA or RNA) are linked together through:', options: ['Peptide bonds', 'Glycosidic bonds only', 'Phosphodiester bonds', 'Hydrogen bonds'], correctIndex: 2, explanation: 'Nucleotides are joined by phosphodiester bonds between the phosphate group of one nucleotide and the sugar of the adjacent one.', difficulty: 'medium' },
  { id: 'bmol-48', type: 'mcq', question: 'The two strands of a DNA double helix are held together by:', options: ['Peptide bonds between bases', 'Hydrogen bonds between complementary base pairs', 'Ionic bonds between sugars', 'Glycosidic bonds between phosphates'], correctIndex: 1, explanation: 'The two polynucleotide strands of DNA are held together by hydrogen bonds formed between complementary base pairs (A=T and G≡C).', difficulty: 'easy' },
  { id: 'bmol-49', type: 'mcq', question: 'In the standard base-pairing rules of DNA, adenine pairs with thymine through how many hydrogen bonds, and guanine pairs with cytosine through how many?', options: ['3 bonds for A-T; 2 bonds for G-C', '2 bonds for A-T; 3 bonds for G-C', '2 bonds for both pairs', '3 bonds for both pairs'], correctIndex: 1, explanation: 'Adenine and thymine are connected by 2 hydrogen bonds, whereas guanine and cytosine are connected by 3 hydrogen bonds.', difficulty: 'medium' },
  { id: 'bmol-50', type: 'assertion', question: 'Assertion (A): DNA is generally more chemically stable than RNA.\nReason (R): DNA contains deoxyribose sugar (lacking a hydroxyl group at the 2\' carbon) and thymine instead of uracil, making it less prone to hydrolysis compared to RNA.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The absence of a 2\'-OH group in deoxyribose and the use of thymine make DNA more chemically stable than RNA, correctly explaining the assertion.', difficulty: 'hard' },
  { id: 'bmol-51', type: 'assertion', question: 'Assertion (A): RNA can act as both genetic material and catalyst in certain systems.\nReason (R): RNA molecules exist as a single strand and can fold into complex three-dimensional shapes, some of which have catalytic activity, called ribozymes.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The single-stranded, foldable nature of RNA allows some RNA molecules to have catalytic function (ribozymes), which correctly explains the assertion.', difficulty: 'hard' },
  { id: 'bmol-52', type: 'matching', question: 'Match Column I (nitrogenous base type) with Column II (example):\nColumn I: A. Purine  B. Pyrimidine (in DNA only)  C. Pyrimidine (in RNA only)  D. Pyrimidine (in both DNA and RNA)\nColumn II: i. Uracil  ii. Cytosine  iii. Adenine  iv. Thymine', options: ['A-iii, B-iv, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-iii, B-i, C-iv, D-ii'], correctIndex: 0, explanation: 'Purine — adenine; Pyrimidine in DNA only — thymine; Pyrimidine in RNA only — uracil; Pyrimidine in both — cytosine.', difficulty: 'medium' },
  { id: 'bmol-53', type: 'count', question: 'Consider the following statements about nucleic acids:\n1. A nucleotide contains a nitrogenous base, a pentose sugar and a phosphate group.\n2. Adenine pairs with thymine via 2 hydrogen bonds.\n3. Guanine pairs with cytosine via 2 hydrogen bonds.\n4. RNA contains uracil instead of thymine.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — guanine pairs with cytosine via 3 hydrogen bonds, not 2.', difficulty: 'medium' },
  { id: 'bmol-54', type: 'count', question: 'Consider the following statements comparing DNA and RNA:\n1. DNA contains deoxyribose sugar; RNA contains ribose sugar.\n2. DNA is typically double-stranded; RNA is typically single-stranded.\n3. DNA contains uracil; RNA contains thymine.\n4. Both DNA and RNA contain adenine, guanine and cytosine.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is reversed — DNA contains thymine, and RNA contains uracil.', difficulty: 'medium' },
  { id: 'bmol-55', type: 'statement', question: 'Statement I: In DNA, the amount of adenine always equals the amount of thymine, and the amount of guanine always equals the amount of cytosine (Chargaff\'s rule).\nStatement II: This equivalence exists because A pairs specifically with T and G pairs specifically with C via hydrogen bonding in the double helix.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains Statement I', 'Both statements are correct, but Statement II does not explain Statement I', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'Chargaff\'s rule (Statement I) is a direct consequence of specific complementary base pairing (Statement II) in the DNA double helix.', difficulty: 'hard' },

  // ============ DYNAMIC STATE OF BODY CONSTITUENTS / METABOLISM ============
  { id: 'bmol-56', type: 'mcq', question: 'The concept that biomolecules within a cell are continuously being synthesised and degraded, keeping the cell in a steady, dynamic condition, is described as the:', options: ['Static state of body constituents', 'Dynamic state of body constituents', 'Equilibrium state', 'Resting state'], correctIndex: 1, explanation: 'Despite an unchanging overall concentration, biomolecules are continually synthesised and broken down, a phenomenon called the dynamic state of body constituents.', difficulty: 'medium' },
  { id: 'bmol-57', type: 'mcq', question: 'The sum total of all the chemical reactions occurring within a living organism is referred to as:', options: ['Catabolism only', 'Anabolism only', 'Metabolism', 'Homeostasis'], correctIndex: 2, explanation: 'Metabolism is the sum of all chemical reactions occurring in an organism, and it includes both anabolic (building up) and catabolic (breaking down) reactions.', difficulty: 'easy' },
  { id: 'bmol-58', type: 'mcq', question: 'Reactions that involve breaking down complex substances into simpler ones, usually releasing energy, are called:', options: ['Anabolic reactions', 'Catabolic reactions', 'Amphibolic reactions', 'Endergonic reactions only'], correctIndex: 1, explanation: 'Catabolism refers to the breakdown of complex molecules into simpler ones, generally accompanied by the release of energy.', difficulty: 'easy' },
  { id: 'bmol-59', type: 'mcq', question: 'Reactions that build up complex molecules from simpler ones, usually requiring an input of energy, are called:', options: ['Catabolic reactions', 'Anabolic reactions', 'Hydrolytic reactions', 'Oxidative reactions only'], correctIndex: 1, explanation: 'Anabolism involves the synthesis of complex molecules from simpler ones, generally requiring energy input.', difficulty: 'easy' },
  { id: 'bmol-60', type: 'mcq', question: 'A sequence of enzyme-catalysed reactions in a cell, where the product of one reaction serves as the substrate for the next, is called a:', options: ['Metabolic pathway', 'Single enzyme reaction', 'Isolated reaction', 'Non-catalysed reaction'], correctIndex: 0, explanation: 'A metabolic pathway is a series of linked, enzyme-catalysed reactions occurring in a cell in a defined sequence.', difficulty: 'easy' },
  { id: 'bmol-61', type: 'assertion', question: 'Assertion (A): Metabolism, despite involving thousands of reactions, is best described as an emergent property of the cell as a whole rather than of individual biomolecules.\nReason (R): No single biomolecule in isolation can carry out the coordinated set of reactions constituting metabolism; the property emerges only when biomolecules interact within the organised structure of the living cell.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since metabolic function arises only from the interaction of biomolecules within the cellular context, R correctly explains why metabolism is considered an emergent property.', difficulty: 'hard' },
  { id: 'bmol-62', type: 'count', question: 'Consider the following statements about metabolism:\n1. Metabolism includes both anabolic and catabolic reactions.\n2. Catabolic reactions generally release energy.\n3. Anabolic reactions generally require energy input.\n4. A metabolic pathway consists of a single isolated chemical reaction.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — a metabolic pathway consists of a linked series of reactions, not a single isolated one.', difficulty: 'medium' },

  // ============ ENZYMES: NATURE, CLASSIFICATION, PROPERTIES ============
  { id: 'bmol-63', type: 'mcq', question: 'Almost all enzymes are, by chemical nature:', options: ['Carbohydrates', 'Proteins', 'Lipids', 'Nucleic acids'], correctIndex: 1, explanation: 'Enzymes are proteins (with a few catalytic RNA exceptions called ribozymes) that act as biological catalysts.', difficulty: 'easy' },
  { id: 'bmol-64', type: 'mcq', question: 'The region of an enzyme molecule where the substrate binds and the catalytic reaction occurs is called the:', options: ['Active site', 'Allosteric site', 'Regulatory site', 'Binding pocket only for inhibitors'], correctIndex: 0, explanation: 'The active site is the specific region of an enzyme where the substrate binds and the chemical reaction is catalysed.', difficulty: 'easy' },
  { id: 'bmol-65', type: 'mcq', question: 'The reactant molecule upon which an enzyme acts to convert it into a product is called the:', options: ['Coenzyme', 'Substrate', 'Cofactor', 'Prosthetic group'], correctIndex: 1, explanation: 'A substrate is the specific reactant on which an enzyme acts.', difficulty: 'easy' },
  { id: 'bmol-66', type: 'mcq', question: 'A non-protein component that is essential for the catalytic activity of certain enzymes is called a:', options: ['Substrate', 'Cofactor', 'Product', 'Active site residue'], correctIndex: 1, explanation: 'Some enzymes require additional chemical components called cofactors for their catalytic activity.', difficulty: 'easy' },
  { id: 'bmol-67', type: 'mcq', question: 'Cofactors that are metal ions, such as zinc, are also referred to as:', options: ['Coenzymes', 'Prosthetic groups', 'Metal ion cofactors', 'Isozymes'], correctIndex: 2, explanation: 'Cofactors may be of three types: prosthetic groups, co-enzymes, and metal ions (metal ion cofactors), each associated with the enzyme in a specific way.', difficulty: 'medium' },
  { id: 'bmol-68', type: 'mcq', question: 'A cofactor that is tightly and permanently bound to the enzyme molecule is called a:', options: ['Coenzyme', 'Prosthetic group', 'Metal ion cofactor', 'Substrate'], correctIndex: 1, explanation: 'A prosthetic group is an organic cofactor that is tightly, often covalently, bound to the enzyme, e.g., haem in catalase.', difficulty: 'medium' },
  { id: 'bmol-69', type: 'mcq', question: 'A cofactor that binds loosely to the enzyme, transiently, during catalysis and is usually organic in nature is called a:', options: ['Prosthetic group', 'Coenzyme', 'Apoenzyme', 'Holoenzyme'], correctIndex: 1, explanation: 'A coenzyme is an organic cofactor that associates with the enzyme only transiently, usually during the course of catalysis, e.g., NAD+ and NADP+.', difficulty: 'medium' },
  { id: 'bmol-70', type: 'mcq', question: 'The protein part of an enzyme, when separated from its non-protein cofactor, is called the:', options: ['Holoenzyme', 'Apoenzyme', 'Coenzyme', 'Zymogen'], correctIndex: 1, explanation: 'The apoenzyme is the protein part of the enzyme, which becomes catalytically active only when combined with its cofactor.', difficulty: 'medium' },
  { id: 'bmol-71', type: 'mcq', question: 'The complete, catalytically active enzyme, formed by the union of the apoenzyme and its cofactor, is called the:', options: ['Apoenzyme', 'Holoenzyme', 'Zymogen', 'Isoenzyme'], correctIndex: 1, explanation: 'A holoenzyme is the functional enzyme formed when the apoenzyme (protein part) combines with its cofactor.', difficulty: 'medium' },
  { id: 'bmol-72', type: 'assertion', question: 'Assertion (A): Removal of the cofactor generally results in loss of enzymatic activity, even though the protein portion remains structurally intact.\nReason (R): Many cofactors participate directly in the catalytic mechanism at the active site, and without them, the apoenzyme alone cannot properly bind or convert the substrate.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since cofactors are often directly involved in catalysis, their removal impairs enzymatic function, correctly explaining the assertion as per R.', difficulty: 'hard' },
  { id: 'bmol-73', type: 'matching', question: 'Match Column I (term) with Column II (description):\nColumn I: A. Prosthetic group  B. Coenzyme  C. Metal ion cofactor  D. Apoenzyme\nColumn II: i. Loosely, transiently bound organic cofactor  ii. Tightly bound organic cofactor  iii. Protein part of enzyme without cofactor  iv. Inorganic ion cofactor (e.g., zinc)', options: ['A-ii, B-i, C-iv, D-iii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-ii, B-iv, C-i, D-iii'], correctIndex: 0, explanation: 'Prosthetic group — tightly bound; Coenzyme — loosely, transiently bound; Metal ion cofactor — inorganic ion; Apoenzyme — protein part without cofactor.', difficulty: 'hard' },
  { id: 'bmol-74', type: 'count', question: 'Consider the following statements about cofactors:\n1. Prosthetic groups are tightly bound to the enzyme.\n2. Coenzymes are typically inorganic metal ions.\n3. A holoenzyme is formed by the union of apoenzyme and cofactor.\n4. Removal of a cofactor always leaves enzyme activity unaffected.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (coenzymes are organic, not metal ions), and statement 4 is wrong (cofactor removal usually abolishes activity).', difficulty: 'hard' },

  // ============ MECHANISM OF ENZYME ACTION ============
  { id: 'bmol-75', type: 'mcq', question: 'According to the general mechanism of enzyme action, an enzyme first combines with its substrate to form a transient:', options: ['Enzyme-product complex', 'Enzyme-substrate (ES) complex', 'Coenzyme complex', 'Zymogen complex'], correctIndex: 1, explanation: 'In enzyme catalysis, the enzyme (E) combines with substrate (S) to form an enzyme-substrate complex (ES), which is then converted to product (P), releasing the enzyme.', difficulty: 'easy' },
  { id: 'bmol-76', type: 'mcq', question: 'The property by which an enzyme acts on only one substrate or a closely related group of substrates is called enzyme:', options: ['Specificity', 'Cooperativity', 'Saturation', 'Denaturation'], correctIndex: 0, explanation: 'Enzyme specificity refers to the selective binding of a particular substrate (or a narrow range of substrates) by an enzyme\'s active site.', difficulty: 'easy' },
  { id: 'bmol-77', type: 'mcq', question: 'As the substrate concentration is increased (with enzyme concentration held constant), the rate of an enzyme-catalysed reaction increases and eventually:', options: ['Continues to rise indefinitely without limit', 'Reaches a maximum velocity (Vmax) and levels off due to saturation of active sites', 'Falls to zero abruptly', 'Oscillates periodically'], correctIndex: 1, explanation: 'At high substrate concentrations, all available active sites become saturated, so the reaction rate plateaus at a maximum velocity, Vmax.', difficulty: 'medium' },
  { id: 'bmol-78', type: 'mcq', question: 'Every enzyme shows a characteristic optimum temperature at which its catalytic activity is maximal; activity generally decreases:', options: ['Only at temperatures below the optimum', 'Both below and above this optimum temperature', 'Only above the optimum temperature', 'Temperature has no effect on enzyme activity'], correctIndex: 1, explanation: 'Enzyme activity increases with temperature up to an optimum, beyond which it declines sharply due to denaturation; activity is also reduced at lower temperatures.', difficulty: 'medium' },
  { id: 'bmol-79', type: 'mcq', question: 'Enzymes also show optimum pH activity; most cellular enzymes function best at a pH range of approximately:', options: ['0–2', '6–8', '10–12', '13–14'], correctIndex: 1, explanation: 'Most enzymes exhibit maximal activity within a narrow pH range, typically between pH 6 and 8, close to neutrality (with some exceptions like pepsin).', difficulty: 'medium' },
  { id: 'bmol-80', type: 'mcq', question: 'A substance that closely resembles the substrate in structure and competes with it for binding to the active site, thereby reducing enzyme activity, is called a(n):', options: ['Allosteric activator', 'Competitive inhibitor', 'Coenzyme', 'Prosthetic group'], correctIndex: 1, explanation: 'A competitive inhibitor structurally mimics the substrate and competes for the active site, reducing the enzyme\'s catalytic efficiency.', difficulty: 'medium' },
  { id: 'bmol-81', type: 'mcq', question: 'The effect of a competitive inhibitor on enzyme activity can typically be overcome by:', options: ['Decreasing the substrate concentration', 'Increasing the substrate concentration', 'Lowering the temperature', 'Removing the coenzyme'], correctIndex: 1, explanation: 'Since competitive inhibitors compete with substrate for the active site, increasing substrate concentration can outcompete the inhibitor and restore activity.', difficulty: 'medium' },
  { id: 'bmol-82', type: 'assertion', question: 'Assertion (A): Malonate acts as a competitive inhibitor of succinic dehydrogenase.\nReason (R): Malonate closely resembles succinate, the natural substrate, in structure and can bind to the active site of the enzyme, blocking succinate binding.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Malonate\'s structural similarity to succinate allows it to occupy the active site of succinic dehydrogenase, competitively inhibiting the enzyme, exactly as described in R.', difficulty: 'hard' },
  { id: 'bmol-83', type: 'assertion', question: 'Assertion (A): Beyond the optimum temperature, enzyme activity declines sharply.\nReason (R): High temperatures disrupt the weak, non-covalent bonds maintaining the enzyme\'s tertiary structure, leading to denaturation and loss of catalytic function.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Denaturation of the enzyme\'s tertiary structure at high temperatures directly explains the loss of catalytic activity beyond the optimum temperature.', difficulty: 'medium' },
  { id: 'bmol-84', type: 'assertion', question: 'Assertion (A): Increasing substrate concentration indefinitely does not increase the rate of an enzyme-catalysed reaction indefinitely.\nReason (R): At very high substrate concentrations, all enzyme active sites become saturated, so the reaction rate reaches a maximum (Vmax) and cannot increase further.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Saturation of active sites at high substrate concentrations limits the reaction rate to Vmax, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'bmol-85', type: 'count', question: 'Consider the following statements about factors affecting enzyme activity:\n1. Enzyme activity increases indefinitely with increasing temperature.\n2. Enzymes show a characteristic optimum pH for maximal activity.\n3. Increasing substrate concentration always increases the reaction rate proportionally, with no upper limit.\n4. A competitive inhibitor can be displaced by increasing substrate concentration.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 2 and 4 are correct. Statement 1 is wrong (activity declines beyond an optimum temperature due to denaturation), and statement 3 is wrong (the rate plateaus at Vmax due to saturation).', difficulty: 'hard' },
  { id: 'bmol-86', type: 'count', question: 'Consider the following statements about enzymes:\n1. Almost all enzymes are proteins.\n2. Enzymes lower the activation energy of a reaction.\n3. Enzymes are consumed and destroyed in the reaction they catalyse.\n4. Enzyme activity can be regulated by inhibitors and cofactors.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — enzymes are catalysts and are not consumed; they are regenerated after catalysis and can be reused.', difficulty: 'medium' },
  { id: 'bmol-87', type: 'statement', question: 'Statement I: Enzymes increase the rate of a chemical reaction by lowering its activation energy.\nStatement II: Enzymes alter the equilibrium point of the reaction they catalyse, favouring product formation.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct — enzymes lower activation energy. Statement II is incorrect — enzymes speed up the attainment of equilibrium but do not change the equilibrium position itself.', difficulty: 'hard' },
  { id: 'bmol-88', type: 'statement', question: 'Statement I: Non-competitive inhibitors bind to a site on the enzyme other than the active site.\nStatement II: Binding of a non-competitive inhibitor changes the shape of the active site, reducing the enzyme\'s catalytic efficiency even in the presence of high substrate concentration.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains Statement I', 'Both statements are correct, but Statement II does not explain Statement I', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 1, explanation: 'Both statements are factually correct descriptions of non-competitive inhibition, but Statement II describes a consequence rather than the direct explanation of why the inhibitor binds elsewhere (Statement I is about binding location, not the mechanism of altered efficiency).', difficulty: 'hard' },

  // ============ CLASSIFICATION OF ENZYMES ============
  { id: 'bmol-89', type: 'mcq', question: 'Enzymes are internationally classified and named on the basis of the:', options: ['Reaction they catalyse', 'Number of subunits they possess', 'Molecular weight only', 'The organism they are extracted from'], correctIndex: 0, explanation: 'The International Union of Biochemists classifies enzymes into six major classes based on the type of chemical reaction they catalyse.', difficulty: 'medium' },
  { id: 'bmol-90', type: 'mcq', question: 'Enzymes that catalyse oxidation-reduction reactions between two substrates are classified as:', options: ['Transferases', 'Oxidoreductases', 'Hydrolases', 'Isomerases'], correctIndex: 1, explanation: 'Oxidoreductases catalyse oxidation-reduction reactions, transferring electrons/hydrogen between substrates.', difficulty: 'medium' },
  { id: 'bmol-91', type: 'mcq', question: 'Enzymes that catalyse the transfer of a group (other than hydrogen) from one substrate to another are classified as:', options: ['Transferases', 'Ligases', 'Lyases', 'Hydrolases'], correctIndex: 0, explanation: 'Transferases catalyse the transfer of a functional group, other than hydrogen, from a donor to an acceptor molecule.', difficulty: 'medium' },
  { id: 'bmol-92', type: 'mcq', question: 'Enzymes that catalyse the hydrolysis of ester, ether, peptide, glycosidic or other bonds, involving the addition of water, are classified as:', options: ['Hydrolases', 'Ligases', 'Isomerases', 'Lyases'], correctIndex: 0, explanation: 'Hydrolases catalyse hydrolytic cleavage of bonds (e.g., peptide, glycosidic) with the addition of a water molecule.', difficulty: 'medium' },
  { id: 'bmol-93', type: 'mcq', question: 'Enzymes that catalyse the removal of groups from substrates by mechanisms other than hydrolysis, often generating a double bond, are classified as:', options: ['Lyases', 'Ligases', 'Oxidoreductases', 'Isomerases'], correctIndex: 0, explanation: 'Lyases catalyse the removal of groups from substrates by mechanisms other than hydrolysis, leaving double bonds.', difficulty: 'medium' },
  { id: 'bmol-94', type: 'mcq', question: 'Enzymes that catalyse the rearrangement of atoms within a molecule, converting it into an isomeric form, are classified as:', options: ['Isomerases', 'Ligases', 'Transferases', 'Hydrolases'], correctIndex: 0, explanation: 'Isomerases catalyse the interconversion of optical, geometric or positional isomers.', difficulty: 'medium' },
  { id: 'bmol-95', type: 'mcq', question: 'Enzymes that catalyse the linking together of two molecules using the energy released from the hydrolysis of ATP (or similar molecules) are classified as:', options: ['Ligases', 'Hydrolases', 'Lyases', 'Oxidoreductases'], correctIndex: 0, explanation: 'Ligases (synthetases) catalyse the joining together of two molecules, coupled with the hydrolysis of a high-energy phosphate bond, e.g., ATP.', difficulty: 'medium' },
  { id: 'bmol-96', type: 'matching', question: 'Match Column I (enzyme class) with Column II (type of reaction catalysed):\nColumn I: A. Oxidoreductase  B. Transferase  C. Hydrolase  D. Ligase\nColumn II: i. Joining two molecules using ATP hydrolysis energy  ii. Hydrolytic cleavage of bonds  iii. Oxidation-reduction reaction  iv. Transfer of a group between substrates', options: ['A-iii, B-iv, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-i, D-ii', 'A-iii, B-i, C-iv, D-ii'], correctIndex: 0, explanation: 'Oxidoreductase — oxidation-reduction; Transferase — group transfer; Hydrolase — hydrolytic cleavage; Ligase — joining with ATP hydrolysis.', difficulty: 'hard' },
  { id: 'bmol-97', type: 'count', question: 'Consider the following enzyme classes:\n1. Oxidoreductases\n2. Transferases\n3. Hydrolases\n4. Lyases\n5. Isomerases\n6. Ligases\nHow many of the above are among the six internationally recognised major classes of enzymes?', options: ['Three', 'Four', 'Five', 'Six'], correctIndex: 3, explanation: 'All six listed classes (oxidoreductases, transferases, hydrolases, lyases, isomerases and ligases) constitute the six major internationally recognised enzyme classes.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'bmol-98', type: 'mcq', question: 'Which of the following biomolecules is NOT typically classified as a macromolecule?', options: ['Protein', 'Polysaccharide', 'Amino acid', 'Nucleic acid'], correctIndex: 2, explanation: 'An amino acid is a micromolecule (monomer), not a macromolecule; proteins, polysaccharides and nucleic acids are macromolecules built from such monomers.', difficulty: 'easy' },
  { id: 'bmol-99', type: 'mcq', question: 'Which functional group is common to both amino acids and fatty acids?', options: ['Amino group (–NH2)', 'Carboxyl group (–COOH)', 'Phosphate group', 'Hydroxyl group of sugars'], correctIndex: 1, explanation: 'Both amino acids and fatty acids possess a carboxyl group (–COOH); amino acids additionally have an amino group.', difficulty: 'medium' },
  { id: 'bmol-100', type: 'assertion', question: 'Assertion (A): Enzymes are highly efficient catalysts, often increasing reaction rates by several orders of magnitude compared to uncatalysed reactions.\nReason (R): Enzymes provide an alternative reaction pathway with lower activation energy, allowing more substrate molecules to successfully convert to product per unit time.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Lowering the activation energy (R) directly explains the dramatic increase in reaction rate achieved by enzymes, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'bmol-101', type: 'assertion', question: 'Assertion (A): Fibrous proteins like collagen are generally insoluble in water.\nReason (R): Fibrous proteins have elongated polypeptide chains arranged in parallel along an axis, forming long fibres stabilised by extensive hydrogen bonding, which reduces their interaction with water.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The elongated, tightly bonded fibre-like arrangement of fibrous proteins such as collagen explains their general insolubility in water, matching the reason given.', difficulty: 'hard' },
  { id: 'bmol-102', type: 'assertion', question: 'Assertion (A): Globular proteins are generally water-soluble.\nReason (R): In globular proteins, the polypeptide chain coils and folds around itself, typically orienting hydrophilic groups towards the outer surface where they interact favourably with water.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The characteristic folding of globular proteins, exposing hydrophilic residues on the surface, explains their general water solubility, correctly matching the assertion.', difficulty: 'hard' },
  { id: 'bmol-103', type: 'count', question: 'Consider the following statements about lipids:\n1. Saturated fatty acids contain no carbon-carbon double bonds.\n2. Oils are generally richer in unsaturated fatty acids than solid fats.\n3. Phospholipids are important structural components of cell membranes.\n4. All lipids are polymers made of repeating monomer units.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is incorrect — lipids are generally not true polymers in the same sense as proteins, polysaccharides or nucleic acids.', difficulty: 'hard' },
  { id: 'bmol-104', type: 'count', question: 'Consider the following statements about primary and secondary metabolites:\n1. Primary metabolites like amino acids and sugars have identifiable functions in normal physiological processes.\n2. Secondary metabolites such as alkaloids, flavonoids and essential oils have well-established, universally agreed-upon biological roles in the producing plant.\n3. Rubber, gums, resins and pigments are all examples of secondary metabolites.\n4. Secondary metabolites have great applications in the pharmaceutical industry.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — the physiological role of most secondary metabolites in the plant itself is not always known or established.', difficulty: 'hard' },
  { id: 'bmol-105', type: 'statement', question: 'Statement I: Secondary metabolites are typically involved in essential day-to-day physiological processes such as respiration and photosynthesis, much like primary metabolites.\nStatement II: Compounds such as alkaloids, terpenoids and essential oils are examples of secondary metabolites, often with significant economic and pharmaceutical importance.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — secondary metabolites are typically not involved in the plant\'s essential day-to-day physiology (that role belongs to primary metabolites). Statement II is correct.', difficulty: 'medium' },
  { id: 'bmol-106', type: 'assertion', question: 'Assertion (A): The isoelectric point of an amino acid is the pH at which the molecule carries no net electric charge.\nReason (R): At the isoelectric point, the amino acid exists predominantly as a zwitterion, in which the positive charge on the amino group is exactly balanced by the negative charge on the carboxyl group.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The balanced positive and negative charges in the zwitterionic form at the isoelectric point directly explain why the amino acid carries no net charge at that pH.', difficulty: 'hard' },
  { id: 'bmol-107', type: 'count', question: 'Consider the following statements about metabolic pathways:\n1. A linear metabolic pathway converts a starting substrate into a final product through a series of intermediates.\n2. All metabolic pathways in a cell operate completely independently, with no interconnections.\n3. Enzymes catalysing each step of a metabolic pathway are usually highly specific for their substrate.\n4. The product of one step in a pathway often serves as the substrate for the next enzyme.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — metabolic pathways are highly interconnected within the overall metabolic network of the cell.', difficulty: 'medium' },
  { id: 'bmol-108', type: 'mcq', question: 'Which of the following statements about the structure of a triglyceride (fat) is correct?', options: ['It is formed by esterification of one molecule of glycerol with three fatty acid molecules', 'It is formed by esterification of three molecules of glycerol with one fatty acid molecule', 'It contains a nitrogenous base', 'It is a polymer of glucose units'], correctIndex: 0, explanation: 'A triglyceride is formed when one glycerol molecule is esterified with three fatty acid molecules, releasing three water molecules.', difficulty: 'medium' },
  { id: 'bmol-109', type: 'mcq', question: 'Which of the following best describes an "isozyme" (isoenzyme)?', options: ['Different molecular forms of the same enzyme that catalyse the same reaction but may differ in properties such as substrate affinity', 'A completely different enzyme catalysing a different reaction', 'A cofactor bound to an enzyme', 'An inactive form of an enzyme'], correctIndex: 0, explanation: 'Isozymes are structurally different forms of the same enzyme (often encoded by different genes) that catalyse the same reaction but can differ in kinetic or regulatory properties.', difficulty: 'medium' },
  { id: 'bmol-110', type: 'assertion', question: 'Assertion (A): Enzymes are highly sensitive to changes in pH and temperature.\nReason (R): Since enzymes are proteins, extreme pH or temperature can disrupt the hydrogen bonds and other weak interactions maintaining their three-dimensional structure, leading to denaturation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since enzyme function depends on maintaining a specific 3-D shape, disruption of stabilising bonds under extreme conditions explains enzyme sensitivity to pH and temperature.', difficulty: 'medium' },
  { id: 'bmol-111', type: 'count', question: 'Consider the following statements about nucleotides and their roles:\n1. ATP (adenosine triphosphate) is a nucleotide that acts as the main energy currency of the cell.\n2. NAD+ is a coenzyme derived from a nucleotide, involved in oxidation-reduction reactions.\n3. Nucleotides are used only for building nucleic acids and have no other cellular role.\n4. Cyclic AMP (cAMP), a nucleotide derivative, functions as a secondary messenger in cells.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — nucleotides have diverse roles beyond forming nucleic acids, including energy transfer (ATP) and signalling (cAMP).', difficulty: 'hard' },
  { id: 'bmol-112', type: 'statement', question: 'Statement I: Fibrous proteins such as keratin and collagen primarily provide structural support in organisms.\nStatement II: Globular proteins such as enzymes and haemoglobin are usually involved in dynamic biological functions like catalysis and transport.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly describe the general functional distinction between fibrous (structural) and globular (functional/dynamic) proteins.', difficulty: 'medium' },
  { id: 'bmol-113', type: 'count', question: 'Consider the following statements about the acid-soluble pool of a cell:\n1. It typically contains inorganic ions.\n2. It contains amino acids, nucleotides and various small metabolites.\n3. It contains true macromolecules like DNA and proteins.\n4. Its molecular composition can be used to represent the chemical composition of living tissue at the level of small molecules.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — macromolecules like DNA and proteins fall in the acid-insoluble fraction, not the acid-soluble pool.', difficulty: 'medium' },
  { id: 'bmol-114', type: 'mcq', question: 'Which of the following is an example of a heteropolymer (a polymer built from more than one type of repeating monomer)?', options: ['Cellulose', 'Starch', 'Protein', 'Glycogen'], correctIndex: 2, explanation: 'Proteins are heteropolymers because they are built from up to 20 different types of amino acids, unlike cellulose, starch or glycogen, which are homopolymers of glucose.', difficulty: 'medium' },
  { id: 'bmol-115', type: 'assertion', question: 'Assertion (A): Proteins can act as enzymes, hormones, receptors, and structural components, showing great functional diversity.\nReason (R): The vast number of possible sequences and combinations of the 20 standard amino acids allows proteins to fold into an enormous variety of three-dimensional shapes suited to different functions.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The combinatorial possibilities of amino acid sequences, leading to diverse 3-D structures, directly explain the wide functional diversity of proteins described in the assertion.', difficulty: 'medium' },

  // ============ ADDITIONAL ASSERTION-REASON / STATEMENT / COUNT ============
  { id: 'bmol-116', type: 'assertion', question: 'Assertion (A): Denatured proteins usually lose their biological activity.\nReason (R): Denaturation disrupts the secondary, tertiary and quaternary structure of a protein by breaking non-covalent interactions, without breaking the peptide bonds of the primary structure.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Loss of higher-order structure due to denaturation directly explains the loss of biological activity, even though the primary sequence (peptide bonds) remains intact.', difficulty: 'medium' },
  { id: 'bmol-117', type: 'assertion', question: 'Assertion (A): Water is considered the medium of life.\nReason (R): Most metabolic reactions in the cell occur in an aqueous medium, and water itself often participates directly as a reactant or product (e.g., in hydrolysis and condensation reactions).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The dual role of water as a solvent for metabolism and as a direct participant in biochemical reactions correctly explains why it is regarded as the medium of life.', difficulty: 'medium' },
  { id: 'bmol-118', type: 'assertion', question: 'Assertion (A): A biomacromolecule like a protein does not exist as a single dissolved individual molecule when examined within the intact acid-insoluble fraction of a cell.\nReason (R): In the living cell, macromolecules typically occur in organised, interacting assemblies rather than free molecules, as revealed once the acid-soluble small molecules are removed by TCA treatment.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The organised, interacting nature of macromolecules within the acid-insoluble fraction correctly accounts for why they are not simply free dissolved molecules.', difficulty: 'hard' },
  { id: 'bmol-119', type: 'count', question: 'Consider the following statements about carbohydrates:\n1. Monosaccharides cannot be hydrolysed further into simpler sugar units.\n2. Sucrose is a disaccharide made of glucose and fructose.\n3. Lactose is a disaccharide made of two glucose units.\n4. Oligosaccharides yield 2 to 10 monosaccharide units on hydrolysis.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — lactose is made of glucose and galactose, not two glucose units.', difficulty: 'medium' },
  { id: 'bmol-120', type: 'count', question: 'Consider the following statements about enzyme inhibition:\n1. A competitive inhibitor structurally resembles the substrate.\n2. A non-competitive inhibitor binds at a site distinct from the active site.\n3. Increasing substrate concentration can overcome competitive inhibition but not typically non-competitive inhibition.\n4. All enzyme inhibitors permanently and irreversibly inactivate the enzyme.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — many inhibitors act reversibly, and enzyme activity can often be restored once the inhibitor is removed or displaced.', difficulty: 'hard' },
  { id: 'bmol-121', type: 'count', question: 'Consider the following statements about the classification of biomolecules:\n1. Micromolecules generally have molecular weights less than 1000 Da.\n2. Macromolecules are generally polymers built from repeating monomer units.\n3. Lipids are always classified strictly as macromolecules due to their large size.\n4. Both micromolecules and macromolecules can be found in the acid-insoluble fraction, depending on their solubility.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are broadly correct. Statement 3 is wrong — lipids are not true macromolecules despite appearing in the acid-insoluble fraction, and statement 4 is an overgeneralisation not typically emphasised as correct in this classification.', difficulty: 'hard' },
  { id: 'bmol-122', type: 'statement', question: 'Statement I: All enzymes require a cofactor to become catalytically active.\nStatement II: Some enzymes are fully active as apoenzymes alone, without needing any additional non-protein component.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — not all enzymes require a cofactor; many enzymes are fully functional using only their protein structure. Statement II is correct.', difficulty: 'medium' },
  { id: 'bmol-123', type: 'statement', question: 'Statement I: The rate of an enzyme-catalysed reaction is influenced by substrate concentration, temperature and pH.\nStatement II: Beyond the optimum temperature, an enzyme\'s catalytic rate continues to increase, just at a slower pace.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — beyond the optimum temperature, catalytic rate declines sharply due to denaturation, it does not continue to increase.', difficulty: 'medium' },
  { id: 'bmol-124', type: 'assertion', question: 'Assertion (A): Sucrose is often called a "non-reducing" sugar.\nReason (R): In sucrose, the anomeric carbons of both glucose and fructose are involved in the glycosidic bond, leaving no free aldehyde or ketone group available to act as a reducing agent.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since both anomeric carbons are locked in the glycosidic bond in sucrose, no free reducing group remains, correctly explaining why it is non-reducing.', difficulty: 'hard' },
  { id: 'bmol-125', type: 'count', question: 'Consider the following statements about DNA structure:\n1. The two strands of DNA run antiparallel to each other.\n2. DNA is a right-handed double helix in its most common (B-DNA) form.\n3. The sugar-phosphate backbone lies on the inside of the helix, with bases pointing outward.\n4. One complete turn of the B-DNA helix contains approximately 10 base pairs.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is reversed — the sugar-phosphate backbone lies on the outside of the helix, while the nitrogenous bases point inward, pairing with each other.', difficulty: 'hard' },
];